select case when year(o.order_date) < 2024 then 'before_2024' when year(o.order_date) = 2024 then '2024' else 'after_2024' end order_cohort, count(*) payment_count, count(case when p.method = 'card' then 1 end) card_count from payments p left outer join orders o on p.order_id = o.id where o.customer_id = 40 group by case when year(o.order_date) < 2024 then 'before_2024' when year(o.order_date) = 2024 then '2024' else 'after_2024' end order by card_count
